import backtrader as bt


class MACDHistoZeroCrossStrategy(bt.Strategy):
    params = dict(
        fast_period=12,
        slow_period=26,
        signal_period=9,
        stop_loss_pct=0.02,
    )

    def __init__(self):
        self.macdhisto = bt.indicators.MACDHisto(
            self.data,
            period_me1=self.p.fast_period,
            period_me2=self.p.slow_period,
            period_signal=self.p.signal_period,
        )
        self.histo = self.macdhisto.histo
        self.cross = bt.indicators.CrossOver(self.histo, 0.0)

        self.order = None
        self.stop_order = None
        self.entry_price = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status == order.Completed:
            if order == self.order:
                self.order = None
                self.entry_price = order.executed.price
                if order.isbuy():
                    stop_price = self.entry_price * (1.0 - self.p.stop_loss_pct)
                else:
                    stop_price = self.entry_price * (1.0 + self.p.stop_loss_pct)
                self.stop_order = self.close(exectype=bt.Order.Stop, price=stop_price)
            elif order == self.stop_order:
                self.stop_order = None
                self.entry_price = None
        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            if order == self.order:
                self.order = None
            elif order == self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.cross[0] > 0:
                self.order = self.buy()
            elif self.cross[0] < 0:
                self.order = self.sell()
